import{_ as s,O as a,o as r,c as o,a as i,i as n,f as c}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"D.01　框架自身、解释任务与理论借用","description":"","frontmatter":{"title":"D.01　框架自身、解释任务与理论借用","xkChars":708,"xkLessons":{"D.01":{"title":"D.01　框架自身、解释任务与理论借用","lead":"同一个自动提醒系统，可以在减少漏办方面有效，却没有让申诉变得可用。先把要解释的结果分开，才能知道技术、制度或人的经历各自需要什么材料，也才知道借来的理论究竟帮了什么。","explanation":["原文定位：第4529—4544行；原文锚点 section-d-01；短引文：‘先问要解释的结果，而不是先选最擅长的词汇。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","D.01把解释任务本身列为研究对象。设备为何失效、决定怎样形成、谁承担后果、当事人怎样理解经历，是相邻但不同问题；技术机理、制度权限和行动者经验可能互相校正，也可能分别完成局部解释。先登记结果与任务，再选材料和方法，不让结构、利益、权力、心理、文化或技术凭名气取得永久优先权。正文§1.3—1.10尤其强调知识不必先完全转成结构变量，理解本身也可作为终点。[来源theory-cross]","理论借用至少分五种身份：观察启发帮助发现问题；定义规定词怎么用；可检验机制对实际过程提出会失败的主张；形式推论在明示数学前提下成立；规范选择表达该保护什么与怎样权衡。它们不能互相充当证据。定义某关系叫反馈，不证明现实反馈有效；数学结构成立不证明真实对象符合假设；事实因果有效也不能跳到应当采用。正文§2.2—2.7给出分型、因果、证据、类比和来源责任。[来源theory-cross]","正式映射应说明保留的关系、丢失的区别和能改变结论的情形。同一词在两套理论中可能指不同对象、变量或推理许可，不能逐字替换。若源域关注量守恒而目标域只借“流”的图形，不能将守恒结论带入；若映射压掉了人的拒绝与权利差异，也不能拿简洁表示作处置依据。已有领域方法足够时，只核来源和边界即可，不必额外创造圈层来显示框架参与。","原文自动提醒例是教学例，不是一个已经调查的真实项目。减少漏办是技术任务指标；申诉能否改变错误涉及程序救济；是否被尊重还需使用者实际处境与表达。三种结果可不同步：第一项真实改善应保留，第二项不足也应明确，第三项没有材料就保持未决。统称系统更好会掩盖分歧，而因一项不足否定全部成果也失真。","历史采纳、目录提及、后来发现相容性和分析者新连接须分别登记。原作中实际采用某理论要有相应文本与版本；目录出现名字只证明提及；当前两者可并存不追认过去发生过影响；研究者今天提出的连接是新分析而不是补写作者思想史。同号版本若属于不同文本，其身份仍不同，拿到A的原稿不能补齐B尚未核的原句。这是§16.15—16.16来源与表达边界在图谱中的具体落实。","程序通过、文件齐全和编号闭合支持工程对应性，不支持语义或现实增益。文件可以格式完美但误读概念，引用可以真实但不能支持当前推断。应先核内容与论证，再按用途检查外部事实和使用效果；不能让检查工具的通过提示成为理论正确性的替身。反过来，工程检查确有局部价值，它可以发现漏项或格式错，但须以其实际能力命名。","五类答案分别是概念答案、文本答案、形式答案、领域经验答案、使用效果答案。概念答案厘清用语，文本答案解释原文，形式答案完成条件推导，领域经验答案支持具体世界关系，使用效果答案比较方法实际是否改善工作。它们不是后一类未得就把前面全部取消的成熟阶梯；但前四类已得也不能补出第五类。材料更多、文字更清楚有时有帮助，效果仍要在实际任务中核。","价值比较须固定实际处理内容、任务与相称资源，保留足够强专业方法作对照，并包括未交付、误判、等待和维护负担。若新框架回答了更多任务、使用了更多资料，也应说明多出来的资源，不能把所有结果差异单归于理论。未做比较时诚实保留概念与文本成果，不宣布现实优越、等效或无用。","八个专题定位可这样理解：01.01追踪问题与目标是否变化；01.02分清概念、隐喻、机制、定理；01.03分开有记录的主动取舍与材料未见的历史空白；01.04防止某种解释预先压制领域问题；01.05区分理论本体、应用层和工具包装；01.06检查边界、对象同一性与圈层建构；01.07允许反例、失败及替代退出；01.08核思想框架与Skill工程实现的关系。编号是研究导航，不是本文声称已获得八份原始研究全文。","最强反方担心不预设解释优先次序会使分析失去方向。回应是可以依据任务和已有证据给某种机制主要地位，只是不赋予它跨任务的永久特权。另一反方认为若领域方法已能回答，就说明框架无用；更准确的结论是本次不需要增加表示层，框架的边界核查可以很轻，也可以让位，不能把退让解释成理论必须胜出或彻底失败。"],"distinctions":[{"leftTitle":"领域主要解释","leftText":"依据当前任务与材料选择。","rightTitle":"永久优先地位","rightText":"未看证据即认定所有问题终归某种词汇，原文排除。"},{"leftTitle":"定义与启发","leftText":"规定用语或提出待检问题。","rightTitle":"机制与形式结论","rightText":"分别需要现实可检材料或明示前提证明，不由术语相似推出。"},{"leftTitle":"文本与概念答案","leftText":"可以有独立成立的解释价值。","rightTitle":"现实使用收益","rightText":"需要实际比较，不能由写清楚自动补出。"},{"leftTitle":"历史采用","leftText":"有对应文本与版本记录的使用。","rightTitle":"当前新连接","rightText":"分析者现在提出的关系，不能倒填为历史事实。"},{"leftTitle":"工程闭合","leftText":"文件、编号、格式或流程符合约定。","rightTitle":"语义与经验正确","rightText":"须分别检验解释、证据及实际效果。"}],"boundaries":["原文自动提醒案例是教学构造，本讲不把它包装成真实研究。","取得一份原稿不能填补另一文本的未核句子，同号版本不等于同一对象。","正式映射可以失败，词语相似不保证机制、守恒或规范结论可迁移。","使用效果未测不取消独立文本解释，也不允许宣称现实收益。","研究入口01.01—01.08仅按当前原文解释，未据其编号声称取得全部历史研究。"],"questions":["设备失效能主要由技术解释吗？","为何不能用文件齐全认证语义正确？","已经取得概念、文本和形式答案，使用效果尚无材料，怎么报告？","图谱研究入口编号能证明历史采用吗？"],"diagramPath":"/reading-assets/S-D-01/figures/section-d-01.png","caseLinks":[{"title":"真实方法文件：无障碍评价与用户经验各有证据边界","href":"https://www.w3.org/TR/2026/NOTE-wcag-em-2-20260723/"}],"caseNotes":[{"title":"真实方法文件：无障碍评价与用户经验各有证据边界","text":"W3C于2026年7月23日发布的WCAG-EM2.0 Group Note在Relation to WCAG2 conformance claims指出，仅评价部分网页不足以对整个网站作符合性声明；Involving users说明残障使用者参与可帮助发现专家评价不易发现的障碍，并建议纳入不同能力的真实使用者。这里展示范围限制与人的实际使用材料各有职责，不能由一个技术检查结果包办所有使用结论。","sourceLabel":"W3C WCAG-EM2.0，2026-07-23版本","sourceUrl":"https://www.w3.org/TR/2026/NOTE-wcag-em-2-20260723/","sourceLocator":"文首日期与Status；Relation to WCAG2 conformance claims第1—3段；Involving users唯一正文段","boundary":"只核该方法文件的范围和参与建议，不证明任何网站实际合规、体验改善或本框架历史上采用该文件；Group Note不是新增WCAG规范要求。","href":"https://www.w3.org/TR/2026/NOTE-wcag-em-2-20260723/"}],"sourceRefs":[{"section":"D.01","start_line":4529,"end_line":4544,"startLine":4529,"endLine":4544}],"outputId":"section-d-01","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先明确结果、对象、任务与所需答案类型，保留各领域独立解释职责。","借用理论时标明启发、定义、机制、形式或规范身份，并核正式映射保留和损失的区别。","将技术改善、程序救济和人的经验等结果逐项取证，不互相认证或互相全盘取消。","区分历史采纳、提及、相容和新连接，逐文本逐版本核来源；工程通过只支持工程事实。","若要评价方法使用收益，再用固定任务资源及强专业对照比较，保留失败与总负担。"],"teachingExamples":[{"title":"原文教学例的展开：三种结果并列","text":"假设提醒确实减少漏办，但错误决定的申诉不能改变结果。技术任务得到局部改善，救济仍不足；若想判断使用者是否感到尊重，需要另取其处境和表达材料。这三条不能压成一个系统好坏分数。","assumptions":"沿用原文明确的教学例，未指向真实机构或效果数据。","boundary":"已有局部改善仅在假设内成立，不是现实因果估计。"},{"title":"教学构造：同词异义的映射","text":"假想工程模型的流量按单位时间物质量定义，组织讨论借用流表示信息转述次数。两者都画箭头，不能因此把物质守恒定理用于推断信息理解没有损耗；应另定义变量、检查重复与遗漏。","assumptions":"两种模型为教学示意，不引用真实工程参数。","boundary":"这里只限制跨域推论，不否定有明确数学映射时的形式借用。"},{"title":"教学构造：版本身份不是数字","text":"假想文本A标5.3.1、工具B也标5.3.1，二者内容与版本体系不同。正确记录是各自完整标题、对象及版本，不能凭相同数字认定A已经包含B的论断。","assumptions":"版本例为教学构造；本委托中Skill5.3.1与理论手稿身份确须分别记录。","boundary":"数字相同不能建立来源关系，实际采用仍需各自文本。"}],"counterexamples":[{"identity":"source_counterexample","text":"提醒有帮助，因此用户必然得到尊重且申诉有效。","effect":"三个结果证据职责不同，技术指标不替程序和体验作证。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"使用效果未测，所以已经完成的概念解释和形式证明全部无效。","effect":"缺少第五类答案只限制效果结论，不取消独立成立的其他答案。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"两个文本都写反馈，所以可以直接移植全部因果结论。","effect":"须核对象、变量、映射及目标域材料，词语相同不保证允许推论相同。","sourceIds":["theory"]}],"questionAnswers":[{"question":"设备失效能主要由技术解释吗？","answer":"可以，若任务和材料支持；原文拒绝的是技术在所有任务中的永久优先权。","basis":"本节原文及上述公开推导"},{"question":"为何不能用文件齐全认证语义正确？","answer":"格式对应与概念理解是不同命题，真实引用也可能被用于不支持的推断。","basis":"本节原文及上述公开推导"},{"question":"已经取得概念、文本和形式答案，使用效果尚无材料，怎么报告？","answer":"保留前三类成果，按已具备的领域经验材料另判；明确使用收益未证，不夸大也不全盘取消。","basis":"本节原文及上述公开推导"},{"question":"图谱研究入口编号能证明历史采用吗？","answer":"不能，只能作导航；需取得相应原文版本及实际使用位置。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-01/figures/section-d-01.png","alt":"解释什么结果？，技术／制度／经验，各自可能有答案；借用身份分清，启发／定义／机制，形式／规范；映射可保留什么，丢失什么区别，何种材料会改变结论；采纳／提及／相容，分析者新连接分开；概念文本形式经验，不能自动补出，实际使用收益；比较任务与总负担，强专业对照，保留未交付与失败。作者依D.01绘制；原文提醒例保持教学身份，工程检查不认证语义与现实收益。","caption":"作者依D.01绘制；原文提醒例保持教学身份，工程检查不认证语义与现实收益。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换所问结果与答案类型，显示相应材料；切换历史采纳/新连接标签，保留来源职责。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实方法文件展示评价范围与使用者材料的责任区分，是当前分析者的有限连接，不追认理论历史采纳。"},"openQuestions":["未取得研究入口01.01—01.08所指全部原研究全文，不能据目录复原其全部论证或采纳史。","本讲没有进行真实读者或工具使用效果比较。"],"taskId":"S-D-01","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4525—4544行；每节精确范围见sourceRefs","claim_support":["intro-20-appendix-d：术语、合同、论证责任和原文边界；不据此认证经验事实","D.01：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-cross","title":"Xikari任务、论证身份与来源契约","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§1.3—1.10第99—181行；§2.2—2.7.1第239—355行","claim_support":["领域任务独立性、命题分型、类比与来源关系及答案上限"],"limits":["理论说明不充当外部经验支持。"],"access_status":"read"},{"id":"w3c-em2","title":"WCAG Evaluation Methodology (WCAG-EM) 2.0","url":"https://www.w3.org/TR/2026/NOTE-wcag-em-2-20260723/","source_type":"primary","version_or_date":"W3C Group Note 2026-07-23","locator":"文首日期/Status；Relation to WCAG2 conformance claims第1—3段；Involving users正文段","claim_support":["样本评价不能直接声明整个网站符合；用户参与有助发现专家难发现的障碍"],"limits":["指导性Group Note而非新增规范；不证明具体实施或本框架历史采用。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-01/lecture.md","sourcesPath":"/reading-assets/S-D-01/sources.json","sourceSlicePath":"/reading-assets/S-D-01/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-01/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-01.md","filePath":"theory/appendix-d/d-01.md"}'),l={name:"theory/appendix-d/d-01.md"};function d(p,e,u,m,_,h){const t=a("SectionLesson");return r(),o("div",null,[e[0]||(e[0]=i('<div class="theory-source"><h1 id="section-d-01" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.01</span><span class="xk-num__gap">　</span></span>框架自身、解释任务与理论借用 <a class="header-anchor" href="#section-d-01" aria-label="Permalink to &quot;D.01　框架自身、解释任务与理论借用 {#section-d-01}&quot;">​</a></h1><p>正文连接：§1.3—1.10；§2.2—2.7；§16.15—16.16。研究入口：01.01—01.08。</p><p>先问要解释的结果，而不是先选最擅长的词汇。解释设备为何失效、某项决定为何形成、谁承担后果、当事人如何理解经历，是相邻但不同的任务。技术机理、制度权限与人的经验可以互相校正，也可以各自对一个局部问题提供主要说明。结构、利益、权力、心理、文化或技术不应在见证据前取得永久优先地位。</p><p>理论借用至少区分观察启发、定义、可检验机制、形式推论和规范选择。同一个词出现在两套理论里，并不保证对象、变量或允许的推论相同。一次正式映射应说明保留哪一关系、丢失何种区别，以及什么情形会改变结论；若一个领域方法已能充分回答问题，框架可以只提供来源与边界检查，不必增加圈层。</p><p>教学例：一项自动提醒减少了漏办，但申诉仍无法改变错误。技术任务得到改善，与程序救济不足可以同时成立。若改问使用者是否获得尊重，还需要他们的实际处境和表达材料。把三种结果统称“系统更好”会遮蔽分歧；把其中一项不足当作全部成果无效同样错误。</p><p>理论的历史采纳、目录提及、后来发现的相容性与分析者提出的新连接须分别保留。不同文本的同号版本并不具有相同身份；取得一份原稿，也不能补齐另一来源尚未核对的原句。程序通过、文件齐全和编号闭合只证明相应工程事实，不证明语义正确或现实增益。</p><p>一个分析可以依次得到概念答案、文本答案、形式答案、领域经验答案和使用效果答案。前四类已有答案不因最后一类尚未取得而消失；使用收益也不能由文字更清楚或材料更多代替。判断新增方法的价值，应固定实际处理内容、任务和相称资源，保留强的专业方法作为对照，并把未交付、误判、等待和维护负担纳入比较。</p><p>专题定位：01.01 原始问题与目标变化；01.02 概念、隐喻、机制与定理的身份；01.03 主动取舍与历史空白；01.04 解释优先次序与理论殖民；01.05 框架本体、应用层与工具层；01.06 边界、同一性与圈层建构；01.07 反例、失败、替代与退出；01.08 思想框架与 Skill 工程包装。</p></div>',1)),n(t,{section:"D.01"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const x=s(l,[["render",d]]);export{f as __pageData,x as default};
